    key = entry.get('key', '')
    en = entry.get('en') or key  # Use key as fallback for English
    zh = entry.get('zh', '')

    # Look for key patterns
    if zh and en:
        # Normalize to lowercase for grouping
        en_lower = en.lower()

        # Track patterns
        for pattern in ['vocabulary', 'flashcard', 'card', 'settings', 'word', 'translation', 'learning', 'phrase', 'review']:
            if pattern in en_lower:
                if pattern not in terminology:
                    terminology[pattern] = {}
                if zh not in terminology[pattern]:
                    terminology[pattern][zh] = []
                terminology[pattern][zh].append(key)

# Print inconsistencies
for concept, translations in sorted(terminology.items()):
    if len(translations) > 1:
        print(f"\n=== {concept.upper()} ===")
        for zh_term, keys in sorted(translations.items()):
            print(f"{zh_term}: {len(keys)} entries")
            for k in keys[:2]:
                print(f"  - {k}")
            if len(keys) > 2:
                print(f"  ... and {len(keys)-2} more")

