import json
import re

with open('/tmp/review_all.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

corrections = []

# CRITICAL CONSISTENCY CHECKS

# 1. "Word" (singular) terminology
print("=== WORD/WORDS TERMINOLOGY ===")
word_entries = [(e.get('key'), e.get('en') or e.get('key'), e.get('zh')) for e in data]

# Find all entries with "Word" in English
word_related = {}
for key, en, zh in word_entries:
    if not zh:
        continue

    # Match "word" patterns more carefully
    if re.search(r'\bword\b', en, re.IGNORECASE):
        match = re.search(r'\bword\b', en, re.IGNORECASE).group().lower()
        if match not in word_related:
            word_related[match] = {}
        if zh not in word_related[match]:
            word_related[match][zh] = []
        word_related[match][zh].append(key)

for variant, translations in sorted(word_related.items()):
    print(f"\n'{variant}' in English translates to:")
    for zh, keys in sorted(translations.items()):
        print(f"  '{zh}': {len(keys)} entries - {keys[0]}")

# 2. Consistency check: "Words Learned" vs other "Words" compounds
print("\n\n=== WORDS COMPOUND PHRASES ===")
for entry in data:
    en = entry.get('en') or entry.get('key')
    zh = entry.get('zh', '')

    if not zh:
        continue

    if 'Words' in en and any(w in en for w in ['Learned', 'Saved', 'Total']):
        print(f"{en}: {zh}")

# 3. Check "Vocabulary" vs "词汇" consistency  - should all be 词汇 not 词汇本
print("\n\n=== VOCABULARY TERMINOLOGY ===")
for entry in data:
    en = entry.get('en') or entry.get('key')
    zh = entry.get('zh', '')

    if not zh:
        continue

    # Match vocabulary
    if 'vocabulary' in en.lower() and '词汇' in zh:
        if '词汇本' in zh:
            print(f"USES 词汇本: {en}")
        elif '词汇' in zh:
            print(f"USES 词汇: {en}")

# 4. Check for placeholder issues more carefully
print("\n\n=== PLACEHOLDER VERIFICATION ===")
placeholder_issues = []
for entry in data:
    en = entry.get('en') or entry.get('key')
    zh = entry.get('zh', '')

    if not zh:
        continue

    # Extract all placeholders
    en_placeholders = re.findall(r'%[@\d$llds{}\w]|\\?\$\{[^}]+\}|\%\d\$[a-z@]', str(en), re.IGNORECASE)
    zh_placeholders = re.findall(r'%[@\d$llds{}\w]|\\?\$\{[^}]+\}|\%\d\$[a-z@]', str(zh), re.IGNORECASE)

    if en_placeholders or zh_placeholders:
        if en_placeholders != zh_placeholders:
            # Try to match them more carefully
            if sorted(en_placeholders) != sorted(zh_placeholders):
                placeholder_issues.append({
                    'key': entry.get('key'),
                    'en': en,
                    'zh': zh,
                    'en_ph': en_placeholders,
                    'zh_ph': zh_placeholders
                })

if placeholder_issues:
    print(f"Found {len(placeholder_issues)} potential placeholder mismatches:")
    for issue in placeholder_issues[:5]:
        print(f"\n{issue['key']}:")
        print(f"  EN placeholders: {issue['en_ph']}")
        print(f"  ZH placeholders: {issue['zh_ph']}")

