    private func uploadSection(
        title: String,
        systemImage: String,
        items: Binding<[PhotosPickerItem]>,
        images: [Data],
        isLoading: Bool,
        onAddFiles: @escaping () -> Void,
        onRemove: @escaping (Int) -> Void,
        onDrop: @escaping ([NSItemProvider]) -> Bool,
        onClear: @escaping () -> Void
    ) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack {
                Label(title, systemImage: systemImage)
                    .font(.headline)
                Spacer()
                if !images.isEmpty {
                    Text("\(images.count) 张")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                    Button("清除", role: .destructive, action: onClear)
                        .font(.caption)
                        .buttonStyle(.borderless)
                }
            }

            if images.isEmpty {
                // Empty state doubles as a drag-and-drop target hint.
                VStack(spacing: 6) {
                    Image(systemName: "square.and.arrow.down.on.square")
                        .font(.title2)
                        .foregroundStyle(.secondary)
                    Text("拖放图片到此 · Drag & drop images here")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 16)
                .background(
                    RoundedRectangle(cornerRadius: 10)
                        .strokeBorder(style: StrokeStyle(lineWidth: 1, dash: [5]))
                        .foregroundStyle(.quaternary)
                )
            } else {
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 8) {
                        ForEach(Array(images.enumerated()), id: \.offset) { index, data in
                            thumbnail(data, onRemove: { onRemove(index) })
