                Text(PinyinConverter.coloredPinyin(phrase.chinese))
                    .font(.subheadline)

                Text(phrase.english)
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }

            Spacer()

            Button {
                SpeechService.speakChinese(phrase.chinese)
            } label: {
                Image(systemName: "speaker.wave.2")
                    .foregroundStyle(.tint)
            }
            .buttonStyle(.bordered)
            .controlSize(.small)
        }
        .padding(.vertical, 4)
    }
}

