                        .buttonStyle(.bordered)

                        Button {
                            ClipboardService.copy(phrase.chinese)
                        } label: {
                            VStack(spacing: 4) {
                                Image(systemName: "doc.on.doc")
                                    .font(.title2)
                                Text("Copy")
                                    .font(.caption)
                            }
                        }
                        .buttonStyle(.bordered)

                        Button {
                            let term = SavedTerm(
                                chinese: phrase.chinese,
