                            ClipboardService.copy(content)
                        }
                        exportSuccessMessage = "Copied to Clipboard"
                        showExportSuccess = true
                        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
                            dismiss()
                        }
