        NavigationStack {
            GeometryReader { geometry in
                ScrollView {
                    VStack(spacing: 0) {
                        // Direction toggle
                        directionToggle
                            .padding(.horizontal)
                            .padding(.top, 8)

                        // Source input section
                        sourceInputSection
                            .frame(minHeight: geometry.size.height * 0.35)

                        // Divider with swap button
                        swapDivider

                        // Translation output section
                        translationOutputSection
                            .frame(minHeight: geometry.size.height * 0.35)

                        Spacer(minLength: 20)
                    }
                }
                .onTapGesture {
                    // Dismiss keyboard when tapping outside text editor
                    isInputFocused = false
                }
            }
            .task {
                applyDefaultDirectionIfNeeded()
            }
            .navigationTitle("Translate")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .primaryAction) {
                    Button {
                        clearAll()
                    } label: {
                        Image(systemName: "trash")
                    }
                    .disabled(!sharedState.hasContent)
                }
            }
            .translationTask(translationConfiguration) { session in
                await performTranslation(session: session)
            }
            .sheet(isPresented: $showLiveSpeechTranslation) {
                LiveSpeechTranslationView(
                    translationDirection: sharedState.direction,
                    onUseTranscript: { transcript in
                        // Set the transcript as source text
                        sharedState.sourceText = transcript
                        // Trigger translation if auto-translate is off
                        if !autoTranslate {
                            triggerTranslation()
                        }
                    },
                    onUseTranslation: { translation in
                        // Set the transcript as source and translation as result
                        // Detect if the translation is Chinese or English
                        let translationIsChinese = translation.contains { $0.isChineseCharacter }
                        if translationIsChinese {
                            // Translation is Chinese, so source was English
                            // Keep the translated text
                            sharedState.translatedText = translation
                        } else {
                            // Translation is English, so source was Chinese
                            sharedState.translatedText = translation
                        }
                    }
                )
                #if os(iOS)
                .presentationDetents([.large])
                .presentationDragIndicator(.visible)
                #else
                .frame(minWidth: 500, minHeight: 600)
                #endif
            }
        }
